/* regnew: NEW rules, laws and regulations affecting a CA/IL/NV/FL/AZ mortgage broker, Jan 2024 through Oct 31, 2026, newest first. Plain data, no functions. Written 2026-10-31. status: final | effective | proposed | vacated | pending | enacted. verify:true marks items whose date, number or current status could not be confirmed against a primary source on the write date. */
window.REG_NEW=(window.REG_NEW||[]).concat([
{d:"2026-10-28",t:"Fed holds at 3.75-4.00 percent after September 2026 hike; next meeting Dec 8-9",who:"Federal Reserve FOMC",lvl:"federal",st:"",status:"final",what:"At the October 27-28, 2026 meeting the FOMC held the federal funds target at 3.75-4.00 percent on a 10-2 vote, with two members preferring another quarter-point increase. The September 2026 meeting had raised the range 25 basis points from 3.50-3.75 percent, the first hike since 2023, after three cuts in late 2025 brought the range down from 4.25-4.50. Futures lean toward another hike in December. Mortgage rates track the 10-year Treasury and MBS spreads rather than the funds rate, but the shift from easing to tightening has kept 30-year rates elevated through the fall.",impact:"Refinance volume stays thin; lock discipline matters because rate volatility around FOMC dates and CPI prints has been high. ARM and temporary buydown products regain relevance for payment-sensitive buyers, and seller credits toward buydowns are a common structure in slow Southern California and Las Vegas markets.",action:"Update rate-talk scripts: the Fed hiked in September 2026 and held in October; do not tell clients cuts are imminent. Calendar Dec 8-9 and lock floating files before the announcement if the lender allows.",src:[{t:"CNBC: Fed decision Oct 28, 2026",u:"https://www.cnbc.com/2026/10/28/fed-meeting-today-live-updates.html"},{t:"Fox Business: October FOMC holds steady",u:"https://www.foxbusiness.com/economy/federal-reserve-interest-rate-decision-october-28-2026"}],verify:false},
{d:"2026-10-20",t:"Fannie Mae / Freddie Mac conservatorship exit and IPO: not imminent, still on the table",who:"U.S. Treasury / FHFA / White House",lvl:"federal",st:"",status:"pending",what:"Treasury Secretary Bessent said in an October 20, 2026 report that the government has no agreed plan to return Fannie Mae and Freddie Mac to private control and that any change must preserve mortgage affordability. FHFA Director Pulte had floated a 2025 or early-2026 public offering of about 5 percent of the shares while keeping the GSEs in conservatorship; President Trump has said an offering remains on the table. On October 22 investor Bill Ackman urged a 2027 exit target and the stocks jumped. No offering, exit or legislation has been completed as of October 31, 2026.",impact:"No change to conforming guidelines, loan limits or delivery from the conservatorship debate itself, but the uncertainty affects MBS spreads and the implicit guarantee. An eventual exit could raise guarantee fees and LLPAs, which would push more borrowers toward FHA and VA.",action:"Treat GSE IPO news as market color, not a guideline change; keep quoting current LLPAs and watch FHFA for any capital or g-fee announcements.",src:[{t:"MortgagePoint: Bessent says exit not imminent (Oct 20, 2026)",u:"https://themortgagepoint.com/2026/10/20/bessent-status-of-fannie-freddie-will-be-addressed-eventually/"},{t:"HousingWire: Trump says IPO still on the table",u:"https://www.housingwire.com/articles/fannie-freddie-ipo-trump/"}],verify:false},
{d:"2026-10-15",t:"California FAIR Plan dwelling rate increase (about 29.1 percent approved) and commercial program changes",who:"California Department of Insurance / California FAIR Plan",lvl:"state",st:"CA",status:"effective",what:"The FAIR Plan, California's insurer of last resort, had about 697,000 policies in force by mid-2026, roughly double the 2023 count. CDI approved a dwelling rate increase of about 29.1 percent (the plan requested about 35.6-35.8 percent); sources differ on whether the increase took effect April 1, 2026 or for new and renewal policies on October 15, 2026, and on the exact percentage. Commercial program changes effective October 15, 2026 reduced broker commissions. The Sustainable Insurance Strategy lets admitted carriers use catastrophe models and reinsurance costs in rates in exchange for writing at least 85 percent of their statewide share in distressed areas.",impact:"Fire-zone borrowers in Riverside wine country, De Luz, Ramona, Alpine, Malibu and foothill LA County face FAIR Plan plus DIC policy premiums of $4,000-$10,000 or more, which can break DTI and must be quoted before locking. Lenders require evidence of insurance with adequate dwelling coverage; FAIR Plan caps ($3 million dwelling) can be an issue on high-value homes.",action:"Order insurance quotes at pre-approval on any property in a fire severity zone; build premium into DTI and impounds; keep a list of surplus-lines and admitted carriers writing in distressed zips.",src:[{t:"CDI Sustainable Insurance Strategy",u:"https://www.insurance.ca.gov/01-consumers/180-climate-change/sustainable-insurance-strategy.Cfm"},{t:"Menlo Insurance: FAIR Plan rate increase 2026",u:"https://www.menloinsurance.com/library/guides/california-fair-plan-rate-increase-2026"},{t:"Beinsure: FAIR Plan near 697,000 policies",u:"https://beinsure.com/news/california-insurers-pledge-new-policies/"}],verify:true},
{d:"2026-10-12",t:"FHFA bi-merge credit report move expected but not announced; tri-merge still required",who:"FHFA / Fannie Mae / Freddie Mac",lvl:"federal",st:"",status:"pending",what:"HousingWire and Bloomberg reported in September-October 2026 that FHFA intends to let lenders deliver two-bureau (bi-merge) credit reports instead of tri-merge, with an announcement expected at MBA Annual on October 12, 2026; Director Pulte canceled his appearance and no directive issued. FHFA had reversed a prior bi-merge plan in July 2025 and announced in November 2025 that tri-merge would remain. Credit bureau stocks fell on the reports. Pulte has also said FHFA is studying a single-report option.",impact:"Credit report costs are a growing per-file expense; a bi-merge option would cut cost but raise concerns about score shopping. Until Fannie and Freddie publish Selling Guide changes, lenders require tri-merge reports.",action:"Keep ordering tri-merge; ask the credit vendor about bi-merge pricing and VantageScore 4.0 availability so Steven can switch quickly if FHFA issues the directive.",src:[{t:"HousingWire: FHFA to move Fannie, Freddie to bi-merge",u:"https://www.housingwire.com/articles/fhfa-bi-merge-credit-reports-fannie-freddie/"},{t:"MPA: Pulte expected to announce bi-merge at MBA",u:"https://www.mpamag.com/us/mortgage-industry/industry-trends/fhfas-pulte-expected-to-announce-move-to-bi-merge-credit-checks-at-mba-event/592106"},{t:"National Mortgage Professional: FHFA could shake up credit reports",u:"https://nationalmortgageprofessional.com/news/fhfa-could-shake-credit-reports-bi-merge-move"}],verify:true},
{d:"2026-09-30",t:"California AB 801 Fair Lending Examination Act signed (effective Jan 1, 2027) and AB 2116 expands CFL to small-business financing",who:"California Legislature / Governor Newsom / DFPI",lvl:"state",st:"CA",status:"enacted",what:"AB 801 creates periodic DFPI fair lending examinations of state-chartered banks, credit unions and all CRMLA licensees regardless of HMDA thresholds, with the DFPI directed to evaluate discriminatory effect (disparate impact) under California fair housing law; it takes effect January 1, 2027. AB 2116 (Ch. 823) brings factoring, merchant cash advance and other small-business commercial financing providers and brokers under the California Financing Law with licensing and conduct rules.",impact:"Wholesale lenders licensed under the CRMLA will face California fair lending exams using disparate impact analysis even as HUD moves to drop its federal disparate impact rule, so expect more lender overlays, pricing-exception controls and documentation requests on broker files. AB 2116 means Steven needs a CFL license before brokering MCAs or factoring to business clients.",action:"Keep pricing-exception logs and consistent pre-qualification notes for California files; decline to arrange small-business commercial financing unless Patriot Pacific obtains a CFL license.",src:[{t:"CFS Review: California enacts its Fair Lending Examination Act",u:"https://www.cfsreview.com/2026/10/california-enacts-its-fair-lending-examination-act/"},{t:"MoFo: California expands CFL to small-business commercial financing",u:"https://www.mofo.com/resources/insights/261015-california-expands-california-financing-law"}],verify:false},
{d:"2026-09-30",t:"Fannie Mae and Freddie Mac announce one-time UAD 3.6 exception window through May 19, 2027; mandate still Nov 2, 2026",who:"Fannie Mae / Freddie Mac (FHFA)",lvl:"federal",st:"",status:"final",what:"UAD 3.6 and the redesigned Uniform Residential Appraisal Report become mandatory for all new appraisal submissions to UCDP on November 2, 2026, based on the initial submission date. On September 30, 2026 both GSEs announced a one-time temporary policy exception allowing sellers that need more time to keep submitting legacy UAD 2.6 forms through May 19, 2027, reportedly with reduced functionality (lower CU risk scoring and no collateral rep-and-warrant relief) during a March 1 to May 19, 2027 period. Broad production for UAD 3.6 began January 26, 2026. FHA accepts UAD 3.6 optionally; VA and USDA have not set dates.",impact:"From November 2 appraisals on conventional files will arrive in the new dynamic report format (no 1004/1073 form numbers, new fields, narrative sections), which changes how Steven reads values, condition ratings and ROV packages. Some lenders will take the exception and others will not, so turn times and formats will vary by lender for six months.",action:"Ask each wholesale lender whether it is on UAD 3.6 or the exception; brief agents and borrowers on the new report look; update ROV templates to the new field names.",src:[{t:"Fannie Mae UAD announcements",u:"https://singlefamily.fanniemae.com/delivering/uniform-mortgage-data-program/uniform-appraisal-dataset/uniform-appraisal-dataset-announcements"},{t:"Reggora: UAD 3.6 mandate timeline and FAQ",u:"https://www.reggora.com/uad-3-6"},{t:"Clear Capital: UAD 3.6 guide for 2026",u:"https://www.clearcapital.com/what-is-uad-3-6-how-the-new-appraisal-standard-will-impact-lenders/"}],verify:false},
{d:"2026-09-29",t:"California wildfire and insurance package signed: SB 876 Disaster Recovery Reform Act, AB 1795 Smoke Damage Recovery Act, SB 894 Wildfire Resilience Loan Program, AB 1680 Make It FAIR Act, AB 2724; mortgage forbearance extensions (Sept 15)",who:"California Legislature / Governor Newsom / CDI",lvl:"state",st:"CA",status:"enacted",what:"In September 2026 the Governor signed a wildfire recovery package (September 15) that permanently extends mortgage forbearance protections for disaster-affected homeowners, followed on September 29-30 by SB 876 (insurer disaster recovery plans, faster claim payments, doubled penalties for stalled claims), AB 1795 (first-in-nation smoke damage testing and remediation standards including mortgage relief provisions), SB 894 (a state loan program for home hardening and defensible space, subject to appropriation), AB 1680 (stronger oversight of the FAIR Plan, likely effective Jan 1, 2027) and AB 2724 (penalties up to $5,000 per 30 days for insurers missing filing deadlines). Roughly ten insurance bills were signed in one week.",impact:"Servicers of California loans must honor extended forbearance rights after declared disasters; smoke-damage claims and payouts affect post-fire refinances and payoffs; SB 894 loans may become a funding source for hardening that improves insurability. FAIR Plan oversight changes could alter availability and pricing in 2027.",action:"Add the forbearance and claim-timing rights to the distressed-borrower checklist; watch CDI implementation bulletins and SB 894 funding before promoting it to clients.",src:[{t:"Governor's wildfire recovery package (Sept 15, 2026)",u:"https://www.gov.ca.gov/2026/09/15/governor-newsom-signs-wildfire-recovery-package-to-strengthen-protections-and-focus-on-rebuilding-for-survivors/"},{t:"CDI: Governor signs Disaster Recovery Reform Act",u:"https://www.insurance.ca.gov/0400-news/0102-alerts/2026/Governor-signs-Commissioner-Lara-and-Sen.cfm"},{t:"Insurance Business: California's new wildfire loan law",u:"https://www.insurancebusinessmag.com/us/news/risk-compliance-legal/californias-new-wildfire-loan-law-puts-insurability-at-the-center-592329.aspx"}],verify:true},
{d:"2026-09-28",t:"California SB 296 signed: disabled veterans' property tax exemption expanded to 50 percent of value up to $1 million (lien dates from Jan 1, 2027)",who:"California Legislature / Governor Newsom (Sen. Archuleta)",lvl:"state",st:"CA",status:"enacted",what:"SB 296 expands the Revenue and Taxation Code 205.5 exemption for veterans rated 100 percent disabled (and unmarried surviving spouses) from roughly $178,000-$268,000 of assessed value to an exemption of 50 percent of the home's full value up to $1,000,000, for lien dates beginning January 1, 2027. Sources disagree on the sunset (lien dates before Jan 1, 2032 per Bloomberg Tax; through 2036 per bill trackers) and whether an income tier applies; the chaptered text should be checked. It was signed September 28, 2026 as part of a five-bill veterans package.",impact:"For 100 percent disabled veteran buyers in San Diego, Riverside and Orange counties the annual property tax savings could reach $5,000-$12,000, materially improving DTI once the exemption posts and making VA purchase more affordable; servicers will need escrow re-analysis after assessors apply it in 2027.",action:"Update the dvtax modules and VA pre-qualification worksheet with the SB 296 figures after verifying the enrolled text; prepare a BOE-261-G filing guide for clients closing in late 2026 and 2027.",src:[{t:"Governor's veterans legislation release (Sept 28, 2026)",u:"https://www.gov.ca.gov/2026/09/28/governor-newsom-signs-legislation-supporting-veterans-servicemembers/"},{t:"SB 296 bill page (CalMatters Digital Democracy)",u:"https://calmatters.digitaldemocracy.org/bills/ca_202520260sb296"},{t:"Bloomberg Tax: California expands disabled veterans exemption",u:"https://news.bloomberglaw.com/daily-tax-report-state/california-expands-property-tax-exemption-for-disabled-veterans"}],verify:true},
{d:"2026-09-10",t:"California SB 1119 amends SB 243 companion chatbot law (minor-specific duties revised from Jan 1, 2027); SB 867 bans chatbot toys",who:"California Legislature",lvl:"state",st:"CA",status:"enacted",what:"SB 243 (effective Jan 1, 2026) was the first U.S. law regulating AI companion chatbots, requiring AI disclosure, crisis protocols, minor protections, annual reporting from July 1, 2027 and a private right of action of $1,000 per violation. A tracker reports SB 1119 (approved Sept 10, 2026) rewrites Section 22602 to remove the minor-specific subdivision when it takes effect January 1, 2027, and SB 867 bans toys with companion chatbots until 2031. These amendments could not be confirmed against the enrolled text.",impact:"A broker's customer-service chatbot or AI assistant is unlikely to be a 'companion chatbot' if it is limited to transactional help, but open-ended, relationship-style AI features would trigger SB 243 duties and litigation exposure; any AI must still disclose it is not human when a reasonable person could be misled.",action:"Keep VANESSA and any client-facing bot scoped to mortgage and real estate tasks with a standing AI disclosure; re-check SB 1119 text on leginfo.",src:[{t:"Sen. Padilla: SB 243 signed",u:"https://sd18.senate.ca.gov/news/first-nation-ai-chatbot-safeguards-signed-law"},{t:"AI Laws by State: SB 243 tracker",u:"https://www.ailawsbystate.com/law/CA/sb243-companion-chatbots"},{t:"CASRAI SB 243 guide",u:"https://casrai.org/guides/california-sb-243-companion-chatbot-law"}],verify:true},
{d:"2026-09-09",t:"VantageScore 4.0 opened to all Fannie Mae and Freddie Mac sellers (LL-2026-06 / Bulletin 2026-H)",who:"Fannie Mae / Freddie Mac / FHFA",lvl:"federal",st:"",status:"effective",what:"After a limited rollout that began in May 2026, Fannie Mae Lender Letter LL-2026-06 and Freddie Mac Bulletin 2026-H made VantageScore 4.0 available to every approved seller effective immediately (reported September 9, 2026) with no prior approval, following FHFA Director Pulte's July 2025 direction that the GSEs accept VantageScore 4.0. Tri-merge reports are still required and FICO 10T is approved but not yet accepted for delivery. Bi-merge remains under consideration.",impact:"Lenders may underwrite with VantageScore 4.0, which uses trended data and rental/utility history and can score thin-file and credit-invisible borrowers (helpful for younger military and immigrant borrowers). Pricing and eligibility depend on which score the lender chooses; some lenders will run both.",action:"Ask lenders and the credit vendor whether VantageScore 4.0 is available on tri-merge reports and how LLPAs are mapped; use it as an option for thin-file clients.",src:[{t:"Informative Research: Fannie and Freddie open VantageScore 4.0 to all lenders",u:"https://insights.informativeresearch.com/industry-news/fannie-mae-and-freddie-mac-open-vantagescore-4-0-to-all-lenders"},{t:"Credit Technologies: what changed September 3 (VantageScore)",u:"https://www.credittechnologies.com/post/fhfa-opens-vantagescore-4-0-all-lenders-what-changed-september-3"},{t:"VantageScore mortgage FAQs",u:"https://vantagescore.com/what-we-do/mortgage-faqs"}],verify:true},
{d:"2026-09-02",t:"NFIP reauthorized through December 11, 2026 (after lapses in late 2025 and Feb 1-3, 2026)",who:"Congress (P.L. 119-103, Continuing Appropriations and Extensions Act, 2027)",lvl:"federal",st:"",status:"effective",what:"The National Flood Insurance Program lapsed for 43 days in late 2025 and again February 1-3, 2026 before a February 3 extension to September 30, 2026; the September 2, 2026 continuing resolution extended authorization to December 11, 2026. During a lapse FEMA cannot issue or renew NFIP policies, which stalls closings in Special Flood Hazard Areas unless private flood insurance is used. No long-term reauthorization has passed since 2017.",impact:"Coastal San Diego, Miami-Dade, Las Vegas washes and riverine Chicago properties in SFHAs face closing risk if Congress misses December 11; lenders must accept qualifying private flood policies, which are the backup.",action:"For any SFHA closing scheduled around December 11, 2026, bind the NFIP policy before the deadline or line up a private flood quote; add the lapse date to the pipeline calendar.",src:[{t:"FEMA congressional reauthorization page",u:"https://www.fema.gov/flood-insurance/rules-legislation/congressional-reauthorization"},{t:"Proctor: NFIP extended to Dec 11, 2026",u:"https://proctorlp.com/compliance/nfip-extended-to-december-11-2026/"},{t:"Out of the Storm News NFIP tracker",u:"https://outofthestormnews.com/data/nfip-reauthorization-tracker"}],verify:false},
{d:"2026-08-30",t:"California AB 1018 (Automated Decisions Safety Act) ordered to Senate third reading; final 2026 outcome to verify",who:"California Legislature (Asm. Bauer-Kahan)",lvl:"state",st:"CA",status:"pending",what:"AB 1018 would require developers and deployers of automated decision systems used for consequential decisions (including lending, housing and insurance) to perform impact assessments, give notices, allow opt-outs and human appeal, and maintain audits. It stalled in 2025 as a two-year bill, returned to active consideration in August 2026 and was ordered to third reading in the Senate on August 30, 2026. Whether it passed the Senate by the August 31 deadline and was signed or vetoed by September 30 could not be confirmed from available sources.",impact:"If enacted, any AI tool Steven uses to score, screen or recommend credit decisions for California consumers would need pre-use notices, impact assessments and appeal mechanics, layered on the CPPA ADMT rules that already take effect January 1, 2027 for CCPA-covered businesses.",action:"Check the AB 1018 history on leginfo for a September 2026 chaptering or veto; in the meantime keep humans making credit decisions and document AI assistance as advisory only.",src:[{t:"AB 1018 bill status (leginfo)",u:"https://leginfo.legislature.ca.gov/faces/billStatusClient.xhtml?bill_id=202520260AB1018"},{t:"OCBC: AB 1018 returns to active consideration",u:"https://ocbc.org/ab-1018-bauer-kahan-returns-to-active-consideration-as-ocbc-maintains-opposition/"}],verify:true},
{d:"2026-08-10",t:"HUD supplemental proposed rule on disparate impact: adds Title VI changes and reopens comments on rescinding 24 CFR 100.500",who:"HUD",lvl:"federal",st:"",status:"proposed",what:"HUD proposed on January 14, 2026 to remove its Fair Housing Act disparate impact regulations (subpart G of 24 CFR part 100), leaving the standard to courts under Inclusive Communities, citing Loper Bright. On August 10, 2026 HUD issued a supplemental notice proposing parallel changes to its Title VI regulations and reopening the comment period; DOJ finalized its own Title VI disparate impact rescission on December 9, 2025. No final Fair Housing Act rule has issued as of October 2026.",impact:"Federal disparate impact enforcement in lending is retreating, but the statute, Supreme Court precedent, ECOA, state law (California FEHA; DFPI exams under AB 801 from 2027) and private litigation still recognize disparate impact, so pricing and underwriting consistency remain essential.",action:"No change to fair lending practices; keep pricing exception logs and consistent criteria; monitor for a final HUD rule in late 2026.",src:[{t:"Ballard: HUD proposes to remove disparate impact rule",u:"https://www.consumerfinancemonitor.com/2026/01/14/hud-proposes-to-remove-its-fair-housing-act-disparate-impact-rule/"},{t:"NAA: federal regulatory changes seek to limit disparate impact liability",u:"https://naahq.org/news/federal-regulatory-changes-seek"},{t:"NCSHA: HUD proposes rescission",u:"https://www.ncsha.org/blog/hud-proposes-rescission-of-disparate-impact-rule/"}],verify:false},
{d:"2026-08-06",t:"CFPB sends revised Section 1033 open banking proposal to OIRA; rule remains enjoined",who:"CFPB",lvl:"federal",st:"",status:"pending",what:"The 2024 Personal Financial Data Rights rule (Section 1033) was enjoined by the Eastern District of Kentucky pending CFPB reconsideration after the Bureau told the court the rule was unlawful. The CFPB published an ANPR on August 22, 2025 and reportedly sent a revised proposal to OIRA on August 6, 2026; no revised rule has been published. Separately the CFPB rescinded its nonbank enforcement-order registry rule (announced Oct 29, 2025; Federal Register final rule dated May 1, 2026 per the CFPB site) and withdrew the form-contract registry proposal.",impact:"Consumer-permissioned bank data access (used by asset and income verification vendors) continues under existing APIs and vendor agreements rather than a mandated standard; the nonbank registry no longer requires brokers subject to orders to register.",action:"No action; continue using lender-approved verification vendors with borrower consent; remove any nonbank-registry task from compliance calendars.",src:[{t:"Cozen: Section 1033 enjoined and under reconsideration",u:"https://www.cozen.com/news-resources/publications/2026/section-1033-compliance-date-open-banking-rule-enjoined-and-under-reconsideration"},{t:"Open Banking Tracker: Section 1033 status 2026",u:"https://www.openbankingtracker.com/guides/section-1033-status"},{t:"Holland & Knight: CFPB rescinds nonbank registration regulation",u:"https://www.hklaw.com/en/insights/publications/2025/11/cfpb-rescinds-nonbank-registration-regulation"}],verify:true},
{d:"2026-07-21",t:"USDA guaranteed loan fee reduction, 2026 income limits (PN 657, July 13) and proposed exclusion of commissions from the 6 percent concession cap",who:"USDA Rural Development",lvl:"federal",st:"",status:"final",what:"USDA issued Procedure Notice 657 on July 13, 2026 with new Single Family Housing Guaranteed income limits effective for GUS submissions on or after that date (including pending and manually underwritten files). A July 21, 2026 trade report describes a substantial reduction in guarantee fees for the program (amounts to verify against the USDA notice). A Federal Register proposal (2026-07617) would exclude real estate commission fees from the 6 percent interested-party contribution limit, and a separate proposal on automated lender systems closed comments August 10, 2026.",impact:"Higher income limits and lower fees make USDA 100 percent financing more competitive than FHA in eligible areas (Winchester, Menifee outskirts, Fallbrook, Clark County and Maricopa fringes); excluding buyer-agent commissions from the 6 percent cap would fix a post-NAR-settlement problem for USDA buyers.",action:"Pull the new 2026 income table for each county, confirm the fee change with the lender, and track the commission-exclusion rule to final.",src:[{t:"Pennymac: USDA 2026 income limits (PN 657)",u:"https://corr.pennymac.com/announcements/announcement-26-82"},{t:"USDA RD bulletin July 2026",u:"https://content.govdelivery.com/accounts/USDARD/bulletins/420d343"},{t:"Federal Register 2026-07617 summary (commissions)",u:"https://policyrisk.com/federal-register/2026-07617"}],verify:true},
{d:"2026-07-13",t:"CFPB request for information on TRID, right of rescission and reverse mortgages; 2026 regulatory agenda lists ATR/QM pre-rule (Aug 2026), Reg X servicing streamlining, COVID rule rescission",who:"CFPB",lvl:"federal",st:"",status:"proposed",what:"Following the March 2026 executive order 'Promoting Access to Mortgage Credit,' the CFPB issued an RFI (July 2026) asking whether TRID timing rules should be replaced with a materiality standard, whether the 3-day CD wait plus 3-day rescission unduly delays refinances, and how reverse mortgage rules should change. The Spring/July 2026 agenda lists ATR/QM as a pre-rule item with activity expected August 2026, a Regulation X servicing streamlining final rule targeted for August 2026, rescission of COVID-era servicing provisions by November 2026, and HMDA threshold review. No final changes to TRID, ATR/QM or Reg X had published as of October 31, 2026.",impact:"Potential future relief on refinance timing and QM definitions, but nothing has changed yet; brokers must keep following current TRID, ATR/QM and servicing rules. Any loosening is likely to come with state pushback in California.",action:"Monitor the Federal Register for ATR/QM and Reg X proposals; consider submitting comments through NAMB; do not change disclosure practices until a final rule and effective date exist.",src:[{t:"Ballard: CFPB issues RFI on TRID, rescission and reverse mortgages",u:"https://www.consumerfinancemonitor.com/2026/07/13/cfpb-issues-rfi-on-trid-rule-rescission-and-reverse-mortgages/"},{t:"Bradley: CFPB's 2026 regulatory agenda",u:"https://www.financialservicesperspectives.com/2026/07/cfpbs-2026-regulatory-agenda-changes-are-coming-for-mortgage-lenders-and-servicers/"},{t:"Troutman: CFPB releases 2026 regulatory agenda",u:"https://www.consumerfinancialserviceslawmonitor.com/2026/07/cfpb-releases-2026-regulatory-agenda-detailing-planned-rulemakings/"}],verify:false},
{d:"2026-07-01",t:"LA Measure ULA thresholds rise to $5.4 million / $10.9 million; repeal and reform efforts shelved",who:"City of Los Angeles / LA City Council / Howard Jarvis Taxpayers Association",lvl:"local",st:"City of Los Angeles",status:"effective",what:"Measure ULA's 4 percent and 5.5 percent transfer tax thresholds adjusted for inflation to $5.4 million and $10.9 million for transactions closing after June 30, 2026 (up from $5.3 million/$10.6 million). The City Council declined in January 2026 to place a reform on the June ballot and in June 2026 shelved a November reform measure; the statewide HJTA initiative that would have effectively repealed ULA was withdrawn in late June 2026 after a Sacramento deal. Prop 43 (Nov 2026, two-thirds vote for future citizen special taxes) does not affect ULA; a city measure (Prop TE) would give Palisades Fire properties a ULA break.",impact:"High-end LA City sellers continue to owe 4-5.5 percent of the full price on top of the 0.56 percent base transfer taxes; luxury sales volume remains depressed and some sellers price just under $5.4 million or use installment or entity structures (which may still be taxed).",action:"Keep the ULA tiers in seller net sheets and Section E of the LE for LA City; check the November 2026 results for Prop TE and Prop 43.",src:[{t:"Hanson Bridgett: ULA update with increased thresholds (June 2026)",u:"https://www.hansonbridgett.com/publication/260701_7087_ula_ordinance_update_june"},{t:"LAist: measure to kill mansion tax won't be on November ballot",u:"https://laist.com/news/housing-homelessness/los-angeles-city-mansion-tax-measure-ula-transfer-state-sacramento-ab-736-howard-jarvis-novemeber-ballot-measure"},{t:"LAist: council shelves ballot measure to cancel mansion tax on new apartments",u:"https://laist.com/news/housing-homelessness/los-angeles-city-council-mansion-tax-measure-ula-november-ballot-measure-2026-vote"}],verify:false},
{d:"2026-06-15",t:"VA Partial Claim Program launches (servicer implementation deadline Nov 28, 2026) under the VA Home Loan Program Reform Act",who:"Department of Veterans Affairs",lvl:"federal",st:"",status:"effective",what:"The VA Home Loan Program Reform Act (H.R. 1815), signed July 30, 2025, authorized VA to make partial claims for up to five years, replacing the Veterans Affairs Servicing Purchase (VASP) program that stopped taking new submissions May 1, 2025. VA formally launched the Partial Claim Program June 15, 2026 and gave servicers until November 28, 2026 to implement. The partial claim covers a percentage of the unpaid principal balance (sources cite 20-30 percent; verify the statute) as a zero-interest, deferred junior lien so the veteran can resume payments at the existing rate. It does not reverse earlier VASP modifications.",impact:"Delinquent VA borrowers in San Diego, Riverside and Las Vegas now have a home-retention option that preserves low existing rates, reducing forced refinances and foreclosures; brokers should route distressed VA clients to their servicer's partial claim desk before any refinance discussion.",action:"Add the VA partial claim to the loss-mitigation checklist with the VA loan technician number (877-827-3702); confirm each servicer's rollout date before Nov 28, 2026.",src:[{t:"The Mortgage Reports: how the new VA partial claim works",u:"https://themortgagereports.com/133801/va-partial-claim-program"},{t:"Veterans United: VA Home Loan Reform Act",u:"https://www.veteransunited.com/education/va-home-loan-reform-act/"},{t:"Mission Roll Call: VASP ending May 1",u:"https://missionrollcall.org/veteran-voices/articles/vasp-program-ending-may-1-what-it-means-for-veterans-and-what-comes-next/"}],verify:true},
{d:"2026-06-13",t:"2026 Area Median Income limits effective; Fannie Mae to use DU casefile create date for AMI-based LLPA waivers from Jan 15, 2027",who:"Fannie Mae / Freddie Mac",lvl:"federal",st:"",status:"final",what:"Fannie Mae and Freddie Mac published 2026 AMI limits (Selling Notice / Bulletin 2026-F) effective June 13, 2026 for HomeReady, Home Possible, RefiNow/Refi Possible and the first-time homebuyer and Duty to Serve LLPA waivers. Fannie Mae announced that for DU loans with casefile create dates on or after January 15, 2027 the income-limit test for LLPA waivers will use the casefile create date instead of the application received date; the LLPA matrix was updated September 30, 2026 (value acceptance terminology).",impact:"Borrowers at or below 100 percent AMI (120 percent in high-cost areas like San Diego, Orange and LA) avoid LLPAs, worth 0.5-3 points of price; the timing change means creating the DU casefile promptly after application matters for borderline income.",action:"Update AMI lookup tables for all counties served; from 2027 create DU casefiles the same day as application on waiver-eligible files.",src:[{t:"Pennymac: 2026 AMI limits (Fannie Selling Notice / Freddie Bulletin 2026-F)",u:"https://corr.pennymac.com/non-delegated-announcements/announcement-26-53"},{t:"TENA: Fannie Mae modifies AMI-based LLPA waiver determination",u:"https://www.tenaco.com/fannie-mae-modifies-area-median-income-based-loan-level-price-adjustment-waiver-determination/"},{t:"Fannie Mae LLPA matrix (Sept 30, 2026)",u:"https://singlefamily.fanniemae.com/media/9391/display"}],verify:false},
{d:"2026-04-08",t:"CFPB proposes 53 percent workforce reduction under 6.5 percent funding cap; enforcement and supervision shrink",who:"CFPB / OMB Director Vought (acting) / courts",lvl:"federal",st:"",status:"pending",what:"The 2025 reconciliation act cut the CFPB's funding cap to 6.5 percent of Federal Reserve operating expenses (about $466.8 million for FY2026, below its 2025 payroll). In April 2026 the Bureau filed a plan to cut about 618 positions (53 percent), leaving roughly 550 staff, with the deepest cuts in enforcement and supervision; earlier 90 percent reduction attempts were blocked by courts and a stay allowed review by the incoming director nominee (Brian Johnson). The Bureau has nonetheless kept an active deregulatory rulemaking agenda.",impact:"Federal supervision of small nonbank brokers is minimal in 2026, but state regulators (DFPI, DRE, IDFPR, NV DML, FL OFR, AZ DIFI) and state AGs are filling the gap, and private plaintiffs still enforce TILA, RESPA, FCRA and TCPA. Rules on the books remain enforceable later.",action:"Do not relax compliance; expect state exams and complaints to be the primary risk; keep CFPB complaint-portal monitoring active.",src:[{t:"Ballard: CFPB workforce restructuring plan (Apr 2026)",u:"https://www.consumerfinancemonitor.com/2026/04/08/cfpb-workforce-restructuring-plan-new-cfpb-motion-details-sweeping-proposed-reductions-in-staff-across-all-divisions-while-injunction-remains-in-place/"},{t:"Banking Dive: CFPB floats plan to cut staff in half",u:"https://www.bankingdive.com/news/cfpb-workforce-reduction-plan-vought-cut-53-percent-618-nteu-farman-big-beautiful-fed-funding/816489/"},{t:"Covington: the CFPB in 2026",u:"https://www.cov.com/-/media/files/corporate/publications/2026/01/funding-haze-and-deregulatory-pursuits-the-cfpb-in-2026.pdf"}],verify:false},
{d:"2026-03-19",t:"FinCEN Residential Real Estate Transfer Reporting Rule vacated nationwide (after March 1, 2026 effective date)",who:"U.S. District Court (Texas) / FinCEN",lvl:"federal",st:"",status:"vacated",what:"FinCEN's 2024 rule required settlement agents to report non-financed transfers of residential real estate to legal entities and trusts, with beneficial ownership details. FinCEN delayed the effective date from December 1, 2025 to March 1, 2026 via a September 30, 2025 exemptive order; the rule took effect March 1 and on March 19, 2026 a Texas federal court vacated it in its entirety as exceeding Bank Secrecy Act authority. Geographic Targeting Orders for title companies in designated metros (including Southern California, Clark County, Miami-Dade and Cook County) continue.",impact:"Title and escrow companies no longer file FinCEN real estate reports on all-cash entity purchases, removing a closing-day data collection step; GTO reporting still applies to cash purchases above thresholds in covered counties, and brokers' own AML programs are unchanged.",action:"Remove the FinCEN RRE report from closing checklists; keep AML/SAR program and GTO awareness; watch for a FinCEN appeal or re-proposal.",src:[{t:"Gibson Dunn: FinCEN RRE rule vacated nationwide",u:"https://www.gibsondunn.com/fincen-residential-real-estate-reporting-rule-vacated-nationwide/"},{t:"Holland & Knight: FinCEN delays RRE rule (Oct 2025)",u:"https://www.hklaw.com/en/insights/publications/2025/10/fincen-delays-residential-real-estate-transfer-reporting-rule"},{t:"Old Republic Title: FinCEN reporting page",u:"https://www.oldrepublictitle.com/title-agents/fincen-reporting/"}],verify:false},
{d:"2026-03-13",t:"Executive order 'Promoting Access to Mortgage Credit' directs review of ATR/QM, TRID, HMDA and servicing rules",who:"White House",lvl:"federal",st:"",status:"final",what:"A March 2026 executive order directed the CFPB and federal financial regulators to review and reduce mortgage origination and servicing regulatory burdens, naming ATR/QM standards, TRID timing, HMDA scope (raising asset exemptions and excluding inquiries) and community-bank mortgage access. The CFPB's July 2026 agenda and RFI implement it; no final rule has issued. The exact date and title should be verified against the Federal Register.",impact:"Signals the direction of 2026-2027 federal rulemaking (looser QM, simpler TRID, fewer HMDA reporters) but changes none of today's requirements.",action:"Track the resulting CFPB proposals; no operational change yet.",src:[{t:"SimplifyQC: CFPB 2026 regulatory agenda and the March 2026 executive order",u:"https://news.simplifyqc.com/cfpb-2026-regulatory-agenda-mortgage-rules/"},{t:"Credit Technologies: 2026 HMDA reporting changes",u:"https://www.credittechnologies.com/post/2026-hmda-reporting-changes-lenders"}],verify:true},
{d:"2026-03-05",t:"Homebuyers Privacy Protection Act takes effect: mortgage trigger leads restricted",who:"Congress (H.R. 2808, signed Sept 5, 2025) / CFPB / FTC",lvl:"federal",st:"",status:"effective",what:"The Act amended the Fair Credit Reporting Act so credit bureaus may sell a prescreened list triggered by a mortgage credit inquiry only to a lender with a firm offer of credit that either has the consumer's authorization or originated the consumer's current mortgage, services it, or holds the consumer's deposit account. Signed September 5, 2025, it took effect March 5, 2026 (some sources say March 4). Leads sold before the effective date remain usable.",impact:"Competitor call storms after a credit pull should drop sharply for Steven's applicants; conversely, trigger-lead purchasing is no longer a lawful lead source unless an exception applies, and buying non-compliant data creates FCRA user liability.",action:"Cancel any trigger-lead vendor contracts lacking a documented exception; tell borrowers at application what to expect and recommend OptOutPrescreen and the DNC registry.",src:[{t:"NAMB: Understanding the trigger leads ban",u:"https://www.namb.org/understanding-the-trigger-leads-ban"},{t:"National Mortgage Professional: trigger lead restrictions begin",u:"https://nationalmortgageprofessional.com/news/trigger-lead-restrictions-begin-homebuyers-privacy-protection-act-takes-effect"},{t:"NAR: Congress moves to curb abusive trigger leads",u:"https://www.nar.realtor/news/real-estate-news/protecting-home-buyers-privacy-congress-moves-to-curb-abusive-trigger-leads"}],verify:false},
{d:"2026-02-15",t:"VA announces funding fee deductible as mortgage insurance for tax year 2026; funding fee rates unchanged",who:"Department of Veterans Affairs / IRS",lvl:"federal",st:"",status:"final",what:"VA announced in February 2026 that, beginning with the 2026 tax year, the VA funding fee is treated as a deductible mortgage insurance premium for borrowers who itemize (the mortgage insurance premium deduction was restored by 2025 tax legislation, verify). Funding fee rates remain the April 7, 2023 schedule (2.15 percent first use, 3.3 percent subsequent, 0.5 percent IRRRL) through at least 2031; a House bill (H.R. 9237) to raise the IRRRL fee to 1.42 percent has not passed.",impact:"A talking point for VA purchase and cash-out clients who itemize (less common after the higher standard deduction); no change to pricing or disclosure.",action:"Mention the deduction with a 'consult your tax professional' caveat; keep current funding fee tables.",src:[{t:"VA Loan Network: VA funding fee 2026",u:"https://valoannetwork.com/va-funding-fee-changes-2026/"},{t:"VA Loan Network: Trump and VA home loans in 2026",u:"https://valoannetwork.com/trump-va-home-loans-2026/"}],verify:true},
{d:"2026-01-26",t:"UAD 3.6 broad production begins; legacy 2.6 forms accepted until Nov 1, 2026",who:"Fannie Mae / Freddie Mac",lvl:"federal",st:"",status:"effective",what:"After limited production (Sept 8, 2025 - Jan 25, 2026), all lenders could submit UAD 3.6 appraisal reports to UCDP from January 26, 2026, with either UAD 2.6 or 3.6 accepted until the November 2, 2026 mandate. Freddie Mac's January 2026 announcement set the timeline.",impact:"Lenders and AMCs began migrating; brokers started seeing the new URAR format on some files in 2026.",action:"See the Sept 30, 2026 entry for the mandate and exception; train staff on reading the new report.",src:[{t:"Freddie Mac UAD announcement January 2026 (PDF)",u:"https://sf.freddiemac.com/docs/pdf/announcement_uad_january-2026.pdf"},{t:"McKissock: UAD 3.6 implementation timeline",u:"https://www.mckissock.com/blog/appraisal/the-future-is-now-fannie-mae-and-freddie-mac-announce-uad-3-6-implementation-timeline-and-policy-changes/"}],verify:false},
{d:"2026-01-14",t:"HUD proposes to rescind the Fair Housing Act disparate impact rule (24 CFR 100.500)",who:"HUD",lvl:"federal",st:"",status:"proposed",what:"HUD's proposed rule would remove subpart G of 24 CFR part 100 (the 2013 burden-shifting disparate impact framework, reinstated in 2023) with a 30-day comment period, leaving disparate impact claims to be decided under the statute and Inclusive Communities. HUD stated it does not claim disparate impact liability is invalid. A supplemental notice followed in August 2026; no final rule yet.",impact:"See the Aug 10, 2026 entry; federal agency enforcement of lending disparate impact is receding while state law and private suits continue.",action:"No practice change.",src:[{t:"Troutman: HUD proposes to rescind disparate impact regulations",u:"https://www.consumerfinancialserviceslawmonitor.com/2026/01/hud-proposes-to-rescind-fair-housing-act-disparate-impact-regulations/"},{t:"National Law Review: HUD proposes changes to disparate impact standard",u:"https://natlawreview.com/article/hud-proposes-changes-its-implementation-fair-housing-acts-disparate-impact-standard"}],verify:false},
{d:"2026-01-07",t:"2026 HMDA asset exemption raised to $59 million; Reg Z escrow and QM thresholds indexed for 2026",who:"CFPB",lvl:"federal",st:"",status:"effective",what:"The CFPB's annual adjustment set the HMDA depository asset exemption at $59 million (institutions at or below that as of Dec 31, 2025 are exempt from 2026 data collection), effective January 7, 2026. Companion annual adjustments updated the Reg Z HPML escrow small-creditor asset threshold, HOEPA points-and-fees thresholds and QM loan-amount tiers for 2026 (specific 2026 dollar figures should be pulled from the Federal Register notices). The 25-loan closed-end HMDA threshold is unchanged.",impact:"No change for a broker that does not fund loans; the 2026 HOEPA and QM dollar tiers should be loaded into pricing checks.",action:"Update the HOEPA/QM threshold table in the pricing tool with the 2026 figures from the CFPB notices.",src:[{t:"Ballard: CFPB adjusts HMDA asset exemption threshold (2026)",u:"https://www.consumerfinancemonitor.com/2026/01/07/cfpb-adjusts-hmda-asset-exemption-threshold-2/"},{t:"CFPB final rules page",u:"https://www.consumerfinance.gov/rules-policy/final-rules/"}],verify:true},
{d:"2026-01-06",t:"FCC delays TCPA 'revoke all' cross-channel revocation provision to January 31, 2027",who:"FCC Consumer and Governmental Affairs Bureau (DA 26-12)",lvl:"federal",st:"",status:"final",what:"The FCC's 2024 consent revocation rule took effect April 11, 2025 (any reasonable means of revocation; honor within 10 business days), but the provision requiring that a revocation sent in response to one type of message apply to all future robocalls and robotexts from that caller was delayed to April 11, 2026 and, by a January 6, 2026 order, further to January 31, 2027 while the FCC reconsiders it.",impact:"Brokers must still honor every opt-out quickly, but a STOP to a marketing text does not yet have to cancel transactional loan-status messages under federal law; best practice is to treat any opt-out as global unless the consumer clarifies.",action:"Keep opt-out handling at or near immediate across all channels; calendar Jan 31, 2027 for the cross-channel rule.",src:[{t:"Burr: FCC delays revoke-all rule to Jan 31, 2027",u:"https://www.burr.com/telephone-consumer-protection-act/the-fcc-delays-effective-date-of-tcpa-revoke-all-rule-until-january-31-2027"},{t:"Orrick: FCC extends robocall consent revocation waiver",u:"https://infobytes.orrick.com/2026-01-16/fcc-extends-robocall-consent-revocation-rule-waiver-to-january-2027/"},{t:"Wiley: FCC extends limited waiver",u:"https://www.wiley.law/alert-FCC-Extends-Limited-Waiver-for-Part-of-the-TCPA-Consent-Revocation-Rule"}],verify:false},
{d:"2026-01-01",t:"California laws effective Jan 1, 2026: SB 243 companion chatbots, SB 543 and AB 976 ADU changes, CCPA ADMT/risk assessment/cyber audit regulations, AB 2801 deposit photos",who:"California Legislature / CPPA",lvl:"state",st:"CA",status:"effective",what:"SB 243 (companion chatbot disclosure and safety, private right of action) took effect. SB 543 measures ADU size by interior livable space, requires 15-business-day completeness review and ties impact-fee exemptions to 750 sq ft (ADU) and 500 sq ft (JADU); AB 976 permanently ends owner-occupancy requirements for ADUs permitted after Jan 1, 2026; AB 1154 lets JADUs sharing a bathroom skip owner occupancy; AB 462 (urgency, Oct 2025) removed Coastal Commission appeals for ADUs. The CPPA's regulations on risk assessments, cybersecurity audits and automated decision-making took effect with staggered compliance (risk assessments begin 2026; ADMT by Jan 1, 2027; attestations and audit certifications from April 1, 2028). AB 2801 requires move-in/move-out photos for deposit deductions.",impact:"ADU financing demand rises (Fannie ADU rent, FHA 203(k) ADU, HomeStyle); chatbots used by brokers must disclose AI; CCPA-covered businesses using AI for lending-related decisions must plan ADMT notices for 2027.",action:"Build an ADU financing playbook for San Diego and Riverside homeowners; confirm VANESSA's AI disclosure; assess CCPA threshold status annually.",src:[{t:"BBK: 2026 California new laws (housing)",u:"https://bbklaw.com/resources/la-020326-california-new-laws-key-updates-practical-impacts-housing-law"},{t:"CalaBuilders: California ADU laws 2026 (SB 543, AB 1154, AB 462)",u:"https://calabuilders.com/california-adu-laws-2026/"},{t:"Baker Botts: CPPA finalizes ADMT, risk assessment and cyber audit rules",u:"https://www.bakerbotts.com/thought-leadership/publications/2025/august/a-101-of-the-cppas-finalizes-rules-on-admt-risk-assessments-and-cybersecurity-audits"}],verify:true},
{d:"2026-01-01",t:"Illinois: only IDFPR may issue Private Lender Exemption Certificates for the Anti-Predatory Lending Database",who:"IDFPR",lvl:"state",st:"IL",status:"effective",what:"Beginning January 1, 2026, Private Lender Exemption Certificates (PLECs) for private-lender mortgages on owner-occupied residential property in Cook, Kane, Peoria and Will counties are issued only by IDFPR; title companies and closers can no longer issue them. This follows P.A. 103-1015 (effective Jan 1, 2025), which exempted persons exempt under RMLA Section 1-4(d) from the database, and the 2025 proposed rules on shared appreciation agreements.",impact:"Private-money and seller-carryback closings in Cook County need the IDFPR PLEC in advance; brokers arranging hard-money loans on owner-occupied Chicago property must build in IDFPR processing time.",action:"For Cook County private-lender files, obtain the PLEC from IDFPR before scheduling closing; keep APLD entries current on all other files.",src:[{t:"ATG: new PLEC requirements (effective Jan 1, 2026)",u:"https://www.atgf.com/sites/default/files/communications/2025/12.31.2025_New_PLEC_Requirements.html"},{t:"IDFPR APLD news",u:"https://idfpr.illinois.gov/finlit101/apld/apld-news.html"}],verify:false},
{d:"2026-01-01",t:"2026 conforming loan limits: $832,750 baseline, $1,249,125 ceiling (FHFA, announced Nov 25, 2025)",who:"FHFA",lvl:"federal",st:"",status:"effective",what:"FHFA raised the 2026 one-unit baseline conforming limit 3.26 percent to $832,750 (from $806,500) and the high-cost ceiling to $1,249,125; Alaska, Hawaii, Guam and USVI use $1,249,125 baseline and $1,873,675 ceiling. Limits rose in all but 32 counties. The 2026 limits apply to loans originated or closed on or after January 1, 2026 (many lenders accepted them on December locks).",impact:"San Diego, Orange and Los Angeles counties are at the ceiling; Riverside, Clark, Maricopa, Cook and Miami-Dade near baseline. More buyers qualify for conforming instead of jumbo pricing; VA partial-entitlement math and FHA floors/ceilings keyed off the new numbers.",action:"Load the 2026 county limit file into countylimits.js and quoting tools; prepare for the 2027 announcement in late November 2026.",src:[{t:"Orrick: FHFA announces 2026 conforming loan limits",u:"https://infobytes.orrick.com/2025-12-05/fhfa-announces-2026-increases-to-conforming-loan-limits/"},{t:"NAHB: conforming limits rise to $832,750",u:"https://www.nahb.org/blog/2025/11/2026-conforming-loan-limits"},{t:"FHFA conforming loan limit values",u:"https://www.fhfa.gov/data/conforming-loan-limit-cll-values"}],verify:false},
{d:"2026-01-01",t:"FHA 2026 loan limits: $541,287 floor, $1,249,125 ceiling (ML 2025-23, Dec 11, 2025); HECM limit $1,249,125 (ML 2025-22); no MIP change",who:"HUD / FHA",lvl:"federal",st:"",status:"effective",what:"Mortgagee Letter 2025-23 set the 2026 forward mortgage one-unit floor at $541,287 (65 percent of the conforming baseline) and ceiling at $1,249,125 for case numbers assigned on or after January 1, 2026; multi-unit floors are $693,050 (2), $837,700 (3) and $1,041,125 (4). ML 2025-22 set the HECM maximum claim amount at $1,249,125. HUD has not changed MIP since ML 2023-05 (0.55 percent annual, 1.75 percent upfront); a bill to allow MIP cancellation at 78 percent LTV (H.R. 5508) has not passed.",impact:"FHA remains viable at the ceiling in San Diego/Orange/LA and at the floor or county figure in Riverside, Clark, Maricopa, Cook and Miami-Dade; quote MIP at the 2023 rates and ignore unverified rumors of a 2026 cut.",action:"Update FHA county limits in quoting tools; keep MIP factors at 1.75/0.55 (0.50 with 5 percent down) unless HUD issues a new ML.",src:[{t:"Amerisave: 2026 FHA loan limits (ML 2025-23 summary)",u:"https://www.amerisave.com/learn/fha-loan-limits-things-every-home-buyer-needs-to-know-about-the-to-m-range"},{t:"HUD single family lender page",u:"https://www.hud.gov/hud-partners/single-family-lender"},{t:"Mortgage-info: FHA MIP chart 2026 (no new change as of Oct 2026)",u:"https://mortgage-info.com/blog/fha-mip-chart-2026-mortgage-insurance-premiums"}],verify:true}
]);
/* 2025 and 2024 entries */
window.REG_NEW=(window.REG_NEW||[]).concat([
{d:"2025-12-10",t:"Fed cuts three times in late 2025 (Sept 17, Oct 29, Dec 10) to 3.50-3.75 percent; ends QT Dec 1",who:"Federal Reserve FOMC",lvl:"federal",st:"",status:"final",what:"After holding at 4.25-4.50 percent through mid-2025, the FOMC cut 25 basis points on September 17, 2025 (a 'risk management cut'), again on October 29 (also announcing the end of balance-sheet runoff December 1), and again on December 10, 2025 to 3.50-3.75 percent, adding T-bill purchases to maintain reserves. The easing cycle reversed with a hike in September 2026.",impact:"Mortgage rates improved modestly in late 2025 and spurred a refinance window for 2023-2024 vintage loans at 7 percent or more; by fall 2026 rates had moved back up.",action:"Use the 2025 refinance cohort list for retention outreach when rates dip; keep rate commentary dated.",src:[{t:"PCBB FOMC update Sept 2025",u:"https://www.pcbb.com/industry-insights/economy/2025-09-17-fomc-update-sep-2025"},{t:"PCBB FOMC update Oct 2025",u:"https://www.pcbb.com/industry-insights/economy/2025-10-29-fomc-update-oct-2025"},{t:"Calculated Risk: FOMC preview Dec 2025",u:"https://www.calculatedriskblog.com/2025/12/fomc-preview-25bps-rate-cut-expected.html"}],verify:false},
{d:"2025-12-09",t:"DOJ finalizes rescission of Title VI disparate impact regulations",who:"U.S. Department of Justice",lvl:"federal",st:"",status:"final",what:"DOJ removed disparate impact provisions from its Title VI (federally funded programs) regulations effective December 9, 2025, following an April 2025 executive order against disparate impact liability; HUD's Fair Housing Act proposal followed in January 2026.",impact:"Signals the federal retreat from disparate impact theory; no direct effect on ECOA/FHA private claims or California FEHA.",action:"None beyond monitoring.",src:[{t:"NAA: federal regulatory changes seek to limit disparate impact liability",u:"https://naahq.org/news/federal-regulatory-changes-seek"}],verify:true},
{d:"2025-10-29",t:"CFPB rescinds nonbank enforcement-order registry rule and withdraws form-contract registry proposal",who:"CFPB",lvl:"federal",st:"",status:"final",what:"The CFPB rescinded its 2024 rule creating a public registry of nonbank covered persons subject to agency and court orders (announced October 29, 2025; the CFPB's rules page lists the rescission final rule with a May 1, 2026 date) and withdrew the 2023 proposal for a registry of nonbanks using certain form-contract terms, citing cost and duplication with NMLS and other systems.",impact:"Nonbank brokers and lenders subject to consent orders no longer register with the CFPB; NMLS disclosure obligations remain.",action:"Remove registry tasks from the compliance calendar.",src:[{t:"Scotsman Guide: CFPB cancels pair of nonbank registry rules",u:"https://www.scotsmanguide.com/news/cfpb-cancels-pair-of-nonbank-registry-rules/"},{t:"CFPB: registry rescission page",u:"https://www.consumerfinance.gov/rules-policy/rules-under-development/registry-of-nonbank-covered-persons-subject-to-certain-agency-and-court-orders-proposed-rescission/"}],verify:true},
{d:"2025-10-02",t:"Nevada Division of Mortgage Lending hearing on NAC 645B revisions (mortgage agent/banker/broker terminology); NRS 645B.400 added by 2025 session",who:"Nevada Division of Mortgage Lending / Nevada Legislature",lvl:"state",st:"NV",status:"proposed",what:"The Division noticed an October 2, 2025 adoption hearing on regulations under NAC 645B and NRS 645B revising the terms identifying mortgage agents, mortgage bankers and mortgage brokers and related company provisions; the 2025 Legislature added NRS 645B.400 (2025 Stats. ch. 237), content unconfirmed. Earlier, SB 355 (2023) added NRS 645B.058 permitting remote work locations. Whether the NAC revisions were adopted as proposed could not be confirmed.",impact:"Possible changes to how Nevada licensees are labeled in NMLS and on documents and to supervision/remote-work rules; renewal and CE unaffected.",action:"Check mld.nv.gov for adopted regulation text and update Nevada disclosures and ads if license terminology changed.",src:[{t:"NV DML notice of intent / adoption hearing (2025)",u:"https://mld.nv.gov/uploadedFiles/mldnvgov/content/About/Meetings/2025/NoticeofIntentAdoptionHearing_ADA.pdf"},{t:"NRS 645B (Nevada Legislature)",u:"https://www.leg.state.nv.us/nrs/NRS-645B.html"}],verify:true},
{d:"2025-10-01",t:"Interagency AVM Quality Control Standards rule takes effect",who:"CFPB, OCC, Fed, FDIC, NCUA, FHFA",lvl:"federal",st:"",status:"effective",what:"The final rule (published Aug 7, 2024) requires mortgage originators and secondary-market issuers that use automated valuation models for credit decisions or covered securitization determinations to maintain policies ensuring confidence in estimates, protecting against data manipulation, avoiding conflicts of interest, requiring random sample testing and complying with nondiscrimination laws. It became effective October 1, 2025.",impact:"Lenders' value-acceptance and AVM-based decisions now sit under a formal QC framework; brokers should expect more documentation when an AVM result is disputed and should use the lender's ROV process.",action:"Know which valuation method each lender used on a file; route disputes through ROV.",src:[{t:"CFPB press release: AVM final rule",u:"https://www.consumerfinance.gov/about-us/newsroom/agencies-issue-final-rule-to-help-ensure-credibility-and-integrity-of-automated-valuation-models"},{t:"Mayer Brown: AVM rule now effective (Oct 2025)",u:"https://www.mayerbrown.com/en/insights/publications/2025/10/mortgage-originators-and-secondary-market-participants-take-note-the-final-rule-on-automated-valuation-models-is-now-effective-and-could-apply-to-you"}],verify:false},
{d:"2025-09-23",t:"CPPA regulations on automated decision-making, risk assessments and cybersecurity audits approved (effective Jan 1, 2026; ADMT compliance Jan 1, 2027)",who:"California Privacy Protection Agency / Office of Administrative Law",lvl:"state",st:"CA",status:"final",what:"OAL approved the CPPA's package: risk assessments for high-risk processing (begin 2026, attestations due April 1, 2028), annual cybersecurity audits with revenue-staggered certification deadlines 2028-2030, and ADMT pre-use notices, opt-outs and access rights for significant decisions (financial/lending, housing, employment) with compliance by January 1, 2027.",impact:"Applies only to CCPA-covered businesses, but sets the California standard for AI in lending decisions and will shape lender vendor requirements.",action:"Determine CCPA coverage annually; if covered, inventory AI tools touching lending decisions before 2027.",src:[{t:"Hunton: newly approved CCPA regulations have staggered deadlines",u:"https://www.hunton.com/privacy-and-cybersecurity-law-blog/newly-approved-ccpa-regulations-have-staggered-deadlines-for-compliance"},{t:"CPPA regulations page",u:"https://cppa.ca.gov/regulations/"}],verify:false},
{d:"2025-09-05",t:"Homebuyers Privacy Protection Act signed (H.R. 2808) - trigger leads curtailed from March 2026",who:"Congress / President",lvl:"federal",st:"",status:"enacted",what:"The Act amended FCRA to bar credit bureaus from selling mortgage-inquiry trigger leads except to lenders with a firm offer that have consumer authorization or an existing origination, servicing or account relationship. Signed September 5, 2025; effective 180 days later (March 5, 2026).",impact:"See the March 5, 2026 entry.",action:"See the March 5, 2026 entry.",src:[{t:"Diamond Residential: trigger leads reform becomes law",u:"https://diamondresidential.com/article/trigger-leads-reform-becomes-law"},{t:"Verse.ai: HPPA FAQs",u:"https://verse.ai/blog/homebuyers-privacy-protection-act-faqs/"}],verify:false},
{d:"2025-08-17",t:"Arizona DIFI amends mortgage broker, lender and loan originator rules (A.A.C. Title 20, Ch. 4, Art. 9)",who:"Arizona Department of Insurance and Financial Institutions",lvl:"state",st:"AZ",status:"effective",what:"DIFI's Article 9 amendments (effective August 17, 2025) replaced 'Superintendent' with 'Director,' removed outdated language, allowed electronic recordkeeping without prior written approval, and broadened the lending experience that counts toward the 3-year responsible-individual requirement (at least one year must be lending-related).",impact:"Easier RI qualification and recordkeeping for Patriot Pacific's Arizona license; no change to bonding or CE.",action:"Confirm the Arizona RI and electronic records policy align with the amended rules.",src:[{t:"DIFI Article 9 notice of final rulemaking and effective date (PDF)",u:"https://difi.az.gov/sites/default/files/Art%209%20Announcement%20NFR%20and%20Effective%20Date.pdf"},{t:"WBK: AZ DIFI amends mortgage rules",u:"https://www.thewbkfirm.com/industry/az-difi-amends-mortgage-broker-mortgage-lender-and-loan-originator-rules"}],verify:false},
{d:"2025-08-15",t:"Illinois IDFPR proposes rules for shared appreciation agreements under the RMLA",who:"IDFPR",lvl:"state",st:"IL",status:"proposed",what:"Following the January 1, 2025 amendment bringing shared appreciation agreements (home equity investment products) within the RMLA definition of mortgage loans, IDFPR proposed implementing regulations on August 15, 2025 covering licensing, disclosures and conduct for SAA providers. Final adoption not confirmed.",impact:"HEI/SAA companies marketing to Illinois homeowners need RMLA licensing; brokers referring clients to such products should verify licensure and disclosures.",action:"Verify any Illinois HEI partner's RMLA license before referral.",src:[{t:"Mayer Brown: Illinois proposes SAA regulations",u:"https://www.mayerbrown.com/en/insights/publications/2025/08/illinois-proposes-regulations-governing-shared-appreciation-agreements"}],verify:true},
{d:"2025-07-30",t:"VA Home Loan Program Reform Act signed: partial claim authority, end of VASP",who:"Congress (H.R. 1815) / VA",lvl:"federal",st:"",status:"enacted",what:"The Act authorized VA to make partial claims (deferred, non-interest-bearing junior liens) for five years to cure defaults, codified the wind-down of VASP (which stopped new submissions May 1, 2025) and set program parameters; VA launched the partial claim program June 15, 2026.",impact:"See the June 15, 2026 entry.",action:"See the June 15, 2026 entry.",src:[{t:"Veterans United: VA Home Loan Reform Act",u:"https://www.veteransunited.com/education/va-home-loan-reform-act/"},{t:"VA Loan Network: VA Home Loan Reform Act",u:"https://valoannetwork.com/va-home-loan-reform-act-passes-2025/"}],verify:true},
{d:"2025-07-08",t:"FHFA keeps tri-merge, allows VantageScore 4.0 for GSE loans (reversing the bi-merge plan)",who:"FHFA Director Pulte / Fannie Mae / Freddie Mac",lvl:"federal",st:"",status:"final",what:"In July 2025 FHFA announced that Fannie Mae and Freddie Mac would accept VantageScore 4.0 (alongside Classic FICO) without the previously planned bi-merge requirement, and in November 2025 Pulte confirmed tri-merge would remain. Limited VantageScore rollout started May 2026 and full availability September 2026.",impact:"Set up the 2026 score-choice environment; bi-merge resurfaced as a possibility in fall 2026.",action:"See the Sept 9, 2026 and Oct 12, 2026 entries.",src:[{t:"Brownstein: FHFA reverses course on bi-merge, opens door to VantageScore 4.0",u:"https://www.bhfs.com/insight/fhfa-reverses-course-on-bi-merge-opens-door-to-vantagescore-4-0/"},{t:"Scotsman Guide: Pulte instructs GSEs to accept VantageScore",u:"https://www.scotsmanguide.com/news/pulte-instructs-fannie-mae-and-freddie-mac-to-accept-vantagescore-for-all-lenders/"}],verify:false},
{d:"2025-07-01",t:"California Rosenthal Act extended to covered commercial debts (SB 1286) and California junk-fee law SB 478 (eff. July 1, 2024) one year on",who:"California Legislature",lvl:"state",st:"CA",status:"effective",what:"SB 1286 (2024) extended the Rosenthal Fair Debt Collection Practices Act to collection of covered commercial debts of $500,000 or less effective July 1, 2025. Separately, SB 478 (the Honest Pricing / junk-fee law, Civ. Code 1770(a)(29)) has prohibited advertising a price that excludes mandatory fees since July 1, 2024; it exempts fees required by law and does not apply to TRID-disclosed loan costs, but applies to broker-marketed services and real estate-adjacent fees.",impact:"Any collection of unpaid business-purpose fees from small-business borrowers must follow Rosenthal; advertised fees for services (credit repair, consulting, property management) must be all-in.",action:"Review fee advertising for SB 478 compliance; use a demand letter, not collection tactics, for unpaid fees.",src:[{t:"Civ. Code 1788 et seq. (leginfo)",u:"https://leginfo.legislature.ca.gov/faces/codes_displayText.xhtml?lawCode=CIV&division=3.&title=1.6C.&part=4.&chapter=&article="},{t:"California AG SB 478 guidance",u:"https://oag.ca.gov/consumers/sb478"}],verify:true},
{d:"2025-05-25",t:"FHA removes non-permanent residents from eligibility (ML 2025-09)",who:"HUD / FHA",lvl:"federal",st:"",status:"effective",what:"Mortgagee Letter 2025-09 eliminated FHA Title II and Title I eligibility for non-permanent resident borrowers (visa holders, DACA, asylum applicants) for case numbers assigned on or after May 25, 2025; lawful permanent residents remain eligible with documentation. Industry data showed a sharp drop in FHA purchase loans to non-permanent residents.",impact:"Work-visa and DACA borrowers in Southern California, Las Vegas, Phoenix, Chicago and Miami must use conventional (Fannie/Freddie still allow non-permanent residents with documentation) or non-QM/ITIN programs; FHA pre-approvals issued before May 2025 for these borrowers are no longer valid.",action:"Screen residency status at application and route non-permanent residents to conventional or portfolio programs; update FHA marketing.",src:[{t:"HUD Mortgagee Letter 2025-09 (PDF)",u:"https://www.hud.gov/sites/default/files/OCHCO/documents/2025-09hsgml.pdf"},{t:"NCSHA: ML 2025-09 revisions to residency requirements",u:"https://www.ncsha.org/resource/fha-mortgagee-letter-2025-09-revisions-to-residency-requirements/"}],verify:false},
{d:"2025-05-01",t:"VA stops accepting new VASP (Veterans Affairs Servicing Purchase) submissions",who:"Department of Veterans Affairs",lvl:"federal",st:"",status:"final",what:"VA ended intake for VASP, under which VA bought defaulted loans and modified them at 2.5 percent, effective May 1, 2025 with about one week's notice; VA pointed to the forthcoming partial claim authority (enacted July 30, 2025) as the replacement. A foreclosure moratorium gap followed for some borrowers.",impact:"Distressed VA borrowers between May 2025 and the June 2026 partial claim launch had fewer options; some were pushed into loan modifications at higher market rates.",action:"Identify VA clients modified in 2025 at high rates for potential refinance review.",src:[{t:"Mission Roll Call: VASP ending May 1",u:"https://missionrollcall.org/veteran-voices/articles/vasp-program-ending-may-1-what-it-means-for-veterans-and-what-comes-next/"}],verify:false},
{d:"2025-04-11",t:"FCC TCPA consent revocation rule takes effect (any reasonable means; honor within 10 business days)",who:"FCC",lvl:"federal",st:"",status:"effective",what:"The 2024 TCPA Consent Revocation Order became effective April 11, 2025: consumers may revoke consent by any reasonable means (STOP, QUIT, END, OPT OUT, UNSUBSCRIBE, etc., or any other reasonable message), callers must honor within 10 business days, may send one confirmation text, and may ask the consumer to clarify scope. The 'revoke all' cross-channel provision was delayed (now to Jan 31, 2027).",impact:"Texting platforms must recognize natural-language opt-outs, not just STOP; opt-outs must propagate across dialer and CRM within 10 business days.",action:"Test the CRM/texting tool with non-standard opt-out phrases and confirm suppression timing.",src:[{t:"BCLP: TCPA opt-out rules take effect April 11, 2025",u:"https://www.bclplaw.com/en-US/events-insights-news/the-tcpas-new-opt-out-rules-take-effect-on-april-11-2025-what-does-this-mean-for-businesses.html"},{t:"DNC.com: TCPA changes in 2025",u:"https://www.dnc.com/blog/tcpa-changes-2025"}],verify:false},
{d:"2025-03-26",t:"FinCEN interim final rule exempts domestic companies and U.S. owners from Corporate Transparency Act BOI reporting",who:"FinCEN / Treasury",lvl:"federal",st:"",status:"final",what:"Following litigation and Treasury's March 2, 2025 enforcement pause, FinCEN issued an interim final rule (published and effective March 26, 2025) removing the requirement for domestic reporting companies and U.S. persons to file beneficial ownership information; foreign reporting companies must still file (deadline April 25, 2025 for existing companies) but need not report U.S. beneficial owners.",impact:"Patriot Pacific Financial Corp and Steven's investor clients' domestic LLCs no longer file BOI reports; DSCR lenders still collect ownership information for their own CDD.",action:"Remove CTA BOI filing from entity checklists; keep entity ownership documents for lenders.",src:[{t:"FinCEN BOI page",u:"https://www.fincen.gov/BOI"},{t:"Davis Polk: FinCEN eliminates BOI reporting for U.S. companies",u:"https://www.davispolk.com/insights/client-update/fincen-eliminates-beneficial-ownership-reporting-requirements-u-s-companies"}],verify:false},
{d:"2025-01-24",t:"Eleventh Circuit vacates FCC one-to-one consent rule for lead generation (Insurance Marketing Coalition v. FCC)",who:"U.S. Court of Appeals for the Eleventh Circuit / FCC",lvl:"federal",st:"",status:"vacated",what:"The FCC's December 2023 rule would have required prior express written consent to name a single seller and be 'logically and topically related' to the website where consent was given, effective January 27, 2025. On January 24, 2025 the Eleventh Circuit held the rule exceeded the FCC's TCPA authority and vacated Part III.D of the 2023 order; the FCC had postponed the effective date to January 2026 the same day. The FCC later removed the rule.",impact:"Multi-seller consent forms on comparison and lead sites remain lawful federally, but consent must still clearly identify the seller(s) and be genuinely obtained; Florida's FTSA and other state laws remain stricter.",action:"Require lead vendors to supply the consent language, seller list and TrustedForm/Jornaya proof; prefer exclusive or short seller lists to reduce challenge risk.",src:[{t:"MoFo: Eleventh Circuit vacates one-to-one consent rule",u:"https://www.mofo.com/resources/insights/250130-eleventh-circuit-vacates-fcc-s-tcpa-one-to-one-consent-rule"},{t:"Wiley: 11th Circuit vacates one-to-one rule",u:"https://www.wiley.law/alert-UPDATE-11th-Circuit-Vacates-FCCs-One-to-One-TCPA-Consent-Rule"}],verify:false},
{d:"2025-01-11",t:"Fannie Mae DU 12.0 expands value acceptance (appraisal waivers) and credit assessment changes",who:"Fannie Mae",lvl:"federal",st:"",status:"effective",what:"The DU Version 12.0 release (weekend of January 11, 2025) expanded value acceptance eligibility (reported up to 90 percent LTV on purchases for primary and second homes and more refinances, verify exact thresholds in Selling Guide B4-1.4-10), introduced value acceptance plus property data more broadly, and updated DU's credit risk assessment to consider cash-flow data and remove certain risk factors. Fannie's January 2025 fact sheet lists exclusions (rental income from the subject, gift of equity, lender concerns).",impact:"More purchase files close without a full appraisal (saving $500-$900 and a week), but value acceptance is withdrawn if the lender has reason to doubt value; ROV does not apply to waivers.",action:"Run DU early to see value acceptance offers; explain to buyers and agents when a waiver is offered and when a property data collection is required.",src:[{t:"Fannie Mae value acceptance fact sheet (Jan 2025)",u:"https://singlefamily.fanniemae.com/media/5916/display"},{t:"Fannie Mae selling policy communications",u:"https://singlefamily.fanniemae.com/selling-policy-communications"}],verify:true},
{d:"2025-01-01",t:"Laws effective Jan 1, 2025: CA AB 2905 AI-voice robocall disclosure, CA AB 2992 buyer-broker agreements, IL shared appreciation under RMLA and APLD exemption (P.A. 103-1015), AZ residential rental TPT eliminated (SB 1131), AZ HB 2720 ADU law, FL Amendment 5 homestead indexing, FHA 2025 limits, FHFA 2025 limits",who:"California, Illinois, Arizona, Florida legislatures; HUD; FHFA",lvl:"state",st:"",status:"effective",what:"California: AB 2905 requires AI-generated voice disclosure in prerecorded calls (Pub. Util. Code 2874); AB 2992 requires written buyer-broker agreements before touring and caps terms at 3 months. Illinois: shared appreciation agreements became RMLA mortgage loans; RMLA 1-4(d) exempt persons exempt from the Predatory Lending Database. Arizona: cities' residential rental TPT ended (SB 1131) and cities over 75,000 must allow ADUs (HB 2720). Florida: Amendment 5 indexes the second $25,000 homestead exemption to CPI. FHFA 2025 conforming limit $806,500 / $1,209,750 ceiling; FHA 2025 floor $524,225 / ceiling $1,209,750.",impact:"Multi-state operating changes: AI-voice disclosure in California calling, written buyer agreements on the realty side, better Arizona rental cash flow for DSCR, and 2025 limits (now superseded by 2026).",action:"Confirm each item is reflected in templates and tools; 2025 limits are historical.",src:[{t:"Pub. Util. Code 2874 / AB 2905 (leginfo)",u:"https://leginfo.legislature.ca.gov/faces/billNavClient.xhtml?bill_id=202320240AB2905"},{t:"Arizona DOR residential rental guidelines (TPT change)",u:"https://azdor.gov/business/transaction-privilege-tax/residential-rental-guidelines"},{t:"IDFPR APLD news (P.A. 103-1015)",u:"https://idfpr.illinois.gov/finlit101/apld/apld-news.html"}],verify:true},
{d:"2024-11-26",t:"FHFA 2025 conforming limits announced: $806,500 baseline, $1,209,750 ceiling; FHA 2025 limits $524,225 / $1,209,750 (ML 2024-21, Dec 2024)",who:"FHFA / HUD",lvl:"federal",st:"",status:"effective",what:"FHFA raised the 2025 baseline 5.2 percent to $806,500 with a $1,209,750 ceiling (effective Jan 1, 2025); HUD matched with a $524,225 floor and $1,209,750 ceiling for 2025 case numbers. Superseded by the 2026 limits ($832,750 / $1,249,125; FHA floor $541,287).",impact:"Historical reference for 2025 closings and for comparing year-over-year limit growth.",action:"None; use 2026 limits.",src:[{t:"FHFA conforming loan limit values",u:"https://www.fhfa.gov/data/conforming-loan-limit-cll-values"},{t:"Lower.com 2026 FHA limits by county (with 2025 comparison)",u:"https://www.lower.com/mortgages/fha-loan/fha-limits-by-county"}],verify:true},
{d:"2024-10-31",t:"Fannie Mae/Freddie Mac and FHA reconsideration of value (ROV) requirements take effect",who:"Fannie Mae / Freddie Mac / HUD (ML 2024-07)",lvl:"federal",st:"",status:"effective",what:"Following the July 2024 interagency ROV guidance, the GSEs required lenders to have borrower-initiated ROV processes (Selling Guide updates effective for applications on or after Aug 29, 2024 with full compliance by Oct 31, 2024) and FHA's ML 2024-07 ROV requirements became effective October 31, 2024 (after an extension from Sept 2). Lenders must disclose the ROV process, accept borrower information on errors and omitted comparables, and respond in writing; appraisers must address ROV requests.",impact:"Brokers now have a formal path to challenge low or biased appraisals; a well-prepared ROV package (specific comparables, factual errors) is the only route since brokers cannot contact appraisers about value.",action:"Use the lender's ROV form on every disputed value; keep an ROV template with comparable grids.",src:[{t:"HLC: final interagency ROV guidance",u:"https://www.hlc.com/en/publications/final-interagency-guidance-on-reconsiderations-of-value-of-residential-real-estate"},{t:"Cooley: federal regulators act to enhance property valuations (July 2024)",u:"https://www.cooley.com/news/insight/2024/2024-07-25-federal-regulators-act-to-enhance-property-valuations-during-mortgage-origination-process"}],verify:true},
{d:"2024-08-10",t:"VA Circular 26-24-14: veterans may pay buyer-broker commissions (temporary local variance after NAR settlement)",who:"Department of Veterans Affairs",lvl:"federal",st:"",status:"effective",what:"Issued June 11, 2024 and effective August 10, 2024, the circular lets VA borrowers pay reasonable and customary buyer-broker charges (not financed, and counted in liquid-asset checks) so veterans remain competitive after the NAR settlement's August 17, 2024 practice changes; VA said permanent rulemaking would follow. Some sources claim the VA Home Loan Program Reform Act codified it, which could not be confirmed; the variance remains in effect (verify).",impact:"VA buyers can sign buyer-broker agreements and pay the fee if the seller will not; sellers can still pay it, and seller-paid buyer-agent commissions do not count toward the 4 percent concession cap.",action:"Explain the rule in VA pre-approvals; confirm the variance status with the lender annually.",src:[{t:"Black, Mann & Graham: VA Circular 26-24-14",u:"https://bmandg.com/va-circular-26-24-14-creates-temporary-local-variance-for-veteran-buyers-to-pay-buyer-broker-charges/"},{t:"VA LGY NAR updates (PDF)",u:"https://www.benefits.va.gov/homeloans/documents/docs/lgy-nar-updates.pdf"}],verify:true},
{d:"2024-08-07",t:"AVM Quality Control Standards final rule published in the Federal Register (effective Oct 1, 2025)",who:"CFPB, OCC, Fed, FDIC, NCUA, FHFA",lvl:"federal",st:"",status:"final",what:"The six agencies finalized Dodd-Frank 1473(q) quality control standards for AVMs used in credit decisions and securitizations; published August 7, 2024 with a 12-month-plus-quarter effective date of October 1, 2025.",impact:"See the Oct 1, 2025 entry.",action:"See the Oct 1, 2025 entry.",src:[{t:"KPMG: AVM interagency final rule (updated July 2024)",u:"https://kpmg.com/kpmg-us/content/dam/kpmg/pdf/2024/automated-valuation-models-avms-interagency-final-rule-reg-alert-updated-july-2024.pdf"}],verify:false},
{d:"2024-07-26",t:"Interagency guidance on reconsiderations of value (ROV) finalized",who:"OCC, Fed, FDIC, NCUA, CFPB",lvl:"federal",st:"",status:"final",what:"The agencies finalized non-binding guidance describing risk-management practices for ROVs: clear borrower-facing processes, staff training, timely review, and treatment of ROVs under appraisal independence and fair lending rules. Published in the Federal Register July 26, 2024 (some sources say July 18).",impact:"Set the template that GSEs and FHA made mandatory by October 31, 2024.",action:"See the Oct 31, 2024 entry.",src:[{t:"HLC: final interagency ROV guidance",u:"https://www.hlc.com/en/publications/final-interagency-guidance-on-reconsiderations-of-value-of-residential-real-estate"}],verify:false},
{d:"2024-07-01",t:"California SB 478 'junk fee' law effective; FHA 203(k) overhaul (ML 2024-13) effective Nov 4, 2024",who:"California Legislature / HUD",lvl:"state",st:"CA",status:"effective",what:"SB 478 (Civ. Code 1770(a)(29)) bans advertising a price that excludes mandatory fees other than government taxes and shipping, effective July 1, 2024. Separately, HUD's ML 2024-13 (July 2024) modernized the 203(k) rehabilitation program effective for case numbers on or after November 4, 2024: Limited 203(k) cap raised from $35,000 to $75,000, rehab periods extended to 12 months (Standard) and 9 months (Limited), consultant fees updated, and financing of up to 12 months of mortgage payments during rehab allowed on Standard.",impact:"SB 478 affects any flat-fee services Steven advertises; the 203(k) changes make ADU and renovation financing in older San Diego and LA housing stock far more workable.",action:"Market the Limited 203(k) at $75,000 for ADU conversions and repairs; keep advertised fees all-in.",src:[{t:"California AG SB 478 page",u:"https://oag.ca.gov/consumers/sb478"},{t:"HUD 203(k) program page",u:"https://www.hud.gov/program_offices/housing/sfh/203k"}],verify:true},
{d:"2024-02-08",t:"FCC declaratory ruling: AI-generated voices are 'artificial' voices under the TCPA",who:"FCC",lvl:"federal",st:"",status:"final",what:"The FCC unanimously ruled that calls using AI technologies that generate or simulate human voices (including voice cloning) are artificial or prerecorded voice calls under the TCPA, so they require prior express consent (written consent for marketing) to cell phones and must include identification and opt-out mechanisms. The ruling followed the New Hampshire AI robocall incident and a November 2023 notice of inquiry.",impact:"Any AI voice agent, AI-generated ringless voicemail or cloned-voice outreach to leads is a robocall requiring prior express written consent; California's AB 2905 (2025) adds a disclosure requirement.",action:"Use AI voice only on consented numbers with an AI disclosure at the start of the call; keep humans on cold outreach.",src:[{t:"Hunton: FCC declaratory ruling on AI-generated voice calls",u:"https://huntonak.com/privacy-and-information-security-law/fcc-issues-declaratory-ruling-that-tcpa-applies-to-ai-generated-voice-calls"},{t:"Orrick: did the FCC really ban AI-generated voice calls?",u:"https://www.orrick.com/insights/2024/02/Did-the-FCC-Really-Ban-AI-Generated-Voice-Calls-No-But-Restrictions-Apply"}],verify:false}
]);
